<script setup>
import {computed,onMounted,onBeforeUnmount,ref} from 'vue'
import {api,waitJob} from '../api'
import JobProgress from './JobProgress.vue'
const props=defineProps({collectionId:Number,worldId:Number,workId:Number,audioOnly:Boolean}),emit=defineEmits(['imported'])
const path=ref(''),recursive=ref(true),mode=ref('indexed'),cross=ref(false),scan=ref(null),job=ref(null),report=ref(null),offset=ref(0),selected=ref(new Set()),runs=ref([]),current=ref(null),error=ref(''),busy=ref(false)
const lifecycle=new AbortController();onBeforeUnmount(()=>lifecycle.abort())
const eligible=r=>!r.error&&r.kind!=='bundle'&&(!props.audioOnly||r.kind==='audio'||/\.(lrc|srt|vtt)$/i.test(r.name))
const visible=computed(()=>report.value?.items||[])
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){if(!lifecycle.signal.aborted)error.value=e.message}finally{if(!lifecycle.signal.aborted)busy.value=false}}
async function history(){runs.value=(await api.get('/api/library-imports',{collection_id:props.collectionId})).items}
onMounted(()=>run(history))
async function page(){report.value=await api.get(`/api/project-previews/${scan.value}`,{offset:offset.value,limit:50})}
async function preview(){selected.value=new Set();offset.value=0;job.value=await api.post('/api/project-previews',{path:path.value,recursive:recursive.value});const done=await waitJob(job.value.id,j=>job.value=j,700,lifecycle.signal);if(!done||done.status!=='done')return;scan.value=done.result.report_id;await page()}
function toggle(index){const s=new Set(selected.value);s.has(index)?s.delete(index):s.add(index);selected.value=s}
async function all(){const values=[];for(let start=0;start<report.value.total;start+=100){if(lifecycle.signal.aborted)return;const p=await api.get(`/api/project-previews/${scan.value}`,{offset:start,limit:100});values.push(...p.items.filter(eligible).map(i=>i.index))}selected.value=new Set(values)}
async function follow(data){job.value=data.job;current.value={id:data.import_id};await waitJob(job.value.id,j=>job.value=j,700,lifecycle.signal);if(lifecycle.signal.aborted)return;current.value=await api.get(`/api/library-imports/${data.import_id}`);await history();emit('imported')}
async function start(){await follow(await api.post('/api/library-imports',{report_id:scan.value,indices:[...selected.value],mode:mode.value,collection_id:props.collectionId,world_id:props.worldId||null,work_id:props.workId||null,allow_cross_scope:cross.value}))}
async function inspect(r){current.value=await api.get(`/api/library-imports/${r.id}`);if(r.job_id)job.value=await api.get(`/api/jobs/${r.job_id}`)}
</script>
<template><section class="card grid"><h2>文件夹预览与归档</h2><p class="small muted">复用素材库预览、增量指纹、内容去重和索引。原件不改写；候选分类不代表已确认作品来源。每次扫描最多5000项，请按子目录分批。</p><label class="field">本机资料目录<input v-model="path" placeholder="选择要检查的目录路径"/></label><label class="row"><input v-model="recursive" type="checkbox"/>包括子目录</label><button :disabled="busy||!path" @click="run(preview)">只读扫描预览</button><p v-if="error" class="notice" role="alert">{{error}}</p><JobProgress :job="job"/>
<template v-if="report"><p>{{report.total}}项 · 重复{{report.duplicate_files}} · 缓存复用{{report.reused_hashes}} · 错误{{report.errors}} · 已选择{{selected.size}}</p><div class="row"><button :disabled="busy" @click="run(all)">选择全部可导入项目</button><button :disabled="busy" @click="selected=new Set()">清空选择</button></div><div class="table-scroll"><table><thead><tr><th>选择</th><th>名称/相对目录</th><th>格式/大小</th><th>候选元数据</th><th>重复/诊断</th></tr></thead><tbody><tr v-for="r in visible" :key="r.index"><td><input type="checkbox" :aria-label="'选择 '+r.name" :checked="selected.has(r.index)" :disabled="!eligible(r)||busy" @change="toggle(r.index)"/></td><td>{{r.relative}}</td><td>{{r.kind}} · {{r.bytes??0}}字节</td><td>{{r.audio?[r.audio.title,r.audio.album,r.audio.artist,r.audio.duration?`${r.audio.duration}秒`:null].filter(Boolean).join(' · '):r.candidate}}<small>{{r.reason}}</small></td><td>{{r.error||r.note||((r.existing?.length||r.duplicate_of!=null)?'已有相同内容':'')}}</td></tr></tbody></table></div><nav class="row"><button :disabled="busy||!offset" @click="offset-=50;run(page)">前50项扫描</button><span>{{offset+1}} / {{report.total}}</span><button :disabled="busy||offset+50>=report.total" @click="offset+=50;run(page)">后50项扫描</button></nav><label class="field">存储方式<select v-model="mode"><option value="indexed">原地索引：只保存路径、文本与缓存</option><option value="managed">托管导入：复制到Front，保留原件</option></select></label><label class="row"><input v-model="cross" type="checkbox"/>明确允许引用已有不同世界观/作品的素材</label><button class="primary" :disabled="busy||!selected.size||!collectionId" @click="run(start)">确认所选项目并归档</button></template>
<details><summary>导入历史与恢复</summary><button :disabled="busy" @click="run(history)">刷新导入历史</button><article v-for="r in runs" :key="r.id" class="row"><span>{{r.created_at}} · {{r.mode}} · {{r.status}}</span><button :disabled="busy" @click="run(()=>inspect(r))">查看结果</button><button v-if="['partial','cancelled','interrupted'].includes(r.status)" :disabled="busy" @click="run(async()=>follow(await api.post(`/api/library-imports/${r.id}/resume`)))">继续未完成项</button></article><div v-if="current"><b>{{current.status}} {{current.counts}}</b><p v-for="r in current.items" :key="r.index">#{{r.index}} · {{r.status}} · {{r.message}}</p><small>结果显示前50项；任务按条目持久保存，取消或重启后只继续未完成项。</small></div></details>
</section></template>
<style scoped>.table-scroll{overflow:auto;max-height:440px}td{max-width:250px;overflow-wrap:anywhere}small{display:block;color:var(--muted)}input[type=checkbox]{width:auto}h2{margin:0}</style>
